 static File root(Path base)throws IOException{File r=Files.createTempDirectory(base,"case-").toFile(),d=new File(r,"product-input01");d.mkdir();for(int i=1;i<=8;i++)Files.write(new File(d,String.format("%032x",i)+".aj02").toPath(),JournalLifecycle17.MAGIC);return r;}
